def max_value_on_paths(N, grid_values):
    # Initialize a 2D matrix to store the maximum sum of values collected on each path
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Iterate over the grid values and update the matrix for each position
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            dp[x][y] = value
        else:
            dp[x][y] = max(dp[x - 1][y], dp[x][y - 1]) + value

    # Return the maximum sum of values collected on the two paths
    return dp[N - 1][N - 1]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Populate the table using the grid values
    for x, y, value in grid_values:
        dp[x][y] = value

    # Fill in the table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i != j:
                dp[i][j] = max(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])

    # Return the maximum sum
    return dp[N][N]

