def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        return isbn

    checksum = 0
    for i, c in enumerate(isbn):
        if i % 2 == 0:
            checksum += find_digit(c)
        else:
            checksum += int(c) * 3

    checksum = 10 - (checksum % 10)
    if checksum == 10:
        checksum = 0

    if isbn[-1].isdigit():
        if int(isbn[-1]) == checksum:
            return "Right"
        else:
            return isbn[:-1] + str(checksum)
    else:
        if isbn[-1].isupper():
            return isbn.lower() + str(checksum)
        else:
            return isbn

def find_digit(char: str) -> int:
    if char.isdigit():
        return int(char)
    else:
        return ord(char) - ord('a') + 10

def verify_isbn(isbn: str) -> str:
    isbn_as_list = list(isbn)
    checksum = 0

    # Calculate the checksum
    for i, char in enumerate(isbn_as_list):
        if char == '-':
            continue
        if i % 2 == 0:
            checksum += int(char)
        else:
            checksum += int(char) * 3

    # Calculate the check digit
    check_digit = (10 - (checksum % 10)) % 10

    # If the last digit is 'X', replace it with the calculated check digit
    if isbn_as_list[-1] == 'X':
        isbn_as_list[-1] = str(check_digit)

    # If the checksum is correct, return "Right"
    if int(''.join(isbn_as_list)) % 10 == 0:
        return "Right"

    # If the checksum is incorrect, return the corrected ISBN number
    return ''.join(isbn_as_list)

def verify_isbn(isbn: str) -> str:
    if isbn_valid(isbn):
        return "Right"
    else:
        return isbn_corrected(isbn)

def isbn_valid(isbn: str) -> bool:
    return sum(isbn_to_digits(isbn)) % 10 == 0

def isbn_to_digits(isbn: str) -> list[int]:
    digits = [*map(int, isbn.replace("-", ""))]
    digits.pop()  # Remove check character
    digits.append(98 - (sum(digits) % 100))
    return digits

def isbn_corrected(isbn: str) -> str:
    digits = isbn_to_digits(isbn)
    digits.pop()  # Remove check character
    digits.append(98 - (sum(digits) % 100))
    return "-".join(f"{d}" for d in digits )

