def count_passing_ways(n,m):
    if n==1 or m==0:
        return 1
    elif m==1:
        return n
    else:
        return count_passing_ways(n-1,m-1)+count_passing_ways(n-2,m-1)

def count_passing_ways(n: int, m: int) -> int:
    # Initialize a dictionary to store the number of passing ways for each student
    passing_ways = {}

    # Base case: if there is only one student, there is only one way to pass the ball
    passing_ways[0] = 1

    # Iterate through each of the m passes
    for i in range(m):
        # Iterate through each of the n students
        for j in range(n):
            # If the student is not the starting student, set the number of passing ways
            # to the sum of the previous passing ways of the left and right neighbors
            if j != 0:
                passing_ways[j] += passing_ways[j - 1] + passing_ways[j + 1]
            # If the student is the starting student, set the number of passing ways
            # to the sum of the passing ways of the left and right neighbors
            else:
                passing_ways[j] += passing_ways[n - 1] + passing_ways[1]

    # Return the number of passing ways of the starting student
    return passing_ways[0]

