def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1 or n == m:
        return 0
    if n == 1:
        return 1

    # Initialize a list to store the number of passing ways for each position
    passing_ways = [1] * n

    # Iterate over each position
    for i in range(1, n):
        # Calculate the number of passing ways for each position
        passing_ways[i] = (passing_ways[i - 1] + passing_ways[(i + 1) % n]) % 1000000007

    # Return the number of passing ways for the starting position
    return passing_ways[0]

