def max_happiness(n, m, items):
    # Initialize a dictionary to store the price and importance values for each item
    item_values = {}
    for item in items:
        item_values[item[0]] = item[1]

    # Sort the items by their importance values in descending order
    sorted_items = sorted(item_values.items(), key=lambda x: x[1], reverse=True)

    # Initialize the maximum total importance value as 0
    max_value = 0

    # Iterate through the sorted items and add them to the knapsack until the budget is exceeded
    for item in sorted_items:
        if n - item[0] >= 0:
            max_value += item[1]
            n -= item[0]

    return max_value

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize an empty list to store the items that can be purchased within the budget
    purchasable_items = []

    # Iterate over the items and calculate the total importance value of each item
    for item in items:
        price, importance = item
        # If the price of the item is within the budget, add it to the list of purchasable items
        if price <= n:
            purchasable_items.append(importance)

