def max_energy(beads):
    # Initialize the dp array with the energy corresponding to the first bead
    dp = [beads[0]] * len(beads)

    # Iterate over the remaining beads and compute the maximum energy by merging them
    for i in range(1, len(beads)):
        for j in range(i, len(beads)):
            # Calculate the energy released by merging beads i and j
            energy = beads[i] * beads[j] * beads[i - 1]

            # Update the maximum energy if necessary
            if energy > dp[i]:
                dp[i] = energy

    # Return the maximum energy obtained by optimally merging all beads
    return max(dp)

def max_energy(beads):
    n = len(beads)
    max_energy = 0
    memo = {}

    for i in range(n):
        for j in range(i, 0, -1):
            k = j + i - 1
            if k >= n:
                break
            key = (i, j)
            if key not in memo:
                memo[key] = beads[i] * beads[j] * beads[k]
            else:
                memo[key] = max(memo[key], beads[i] * beads[j] * beads[k])
            max_energy = max(max_energy, memo[key])

    return max_energy

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Examples:

        >>> polynomial_to_string(5, [100, -1, 1, -3, 0, 10])
        '100x^5-x^4+x^3-3x^2+10'

        >>> polynomial_to_string(3, [-50, 0, 0, 1])
        '-50x^3+1'

    """
    if len(coeffs) != n + 1:
        raise ValueError(f"Coefficient length mismatch. Expected length: {n + 1}, Actual: {len(coeffs)}")

    terms = []
    for i in range(1, n+1):
        coeff = coeffs[n - i]
        if coeff != 0:
            term = ""
            if coeff > 0:
                term += "+"
            elif coeff < 0:
                term += "-"
            abs_coeff = abs(coeff)
            if abs_coeff != 1 or i == 1:
                term += str(abs_coeff)
            if i > 1:
                term += "x^" + str(i)
            terms.append(term)

    return "".join(terms)

